#[using="Type"] Lemma art_rta_Cm1 : forall regs (M rom : word -> option byte) (sp r c spb qs total mfa kf q rr addr2 : Z),
  addr2 = spb + c * 2 ^ 32 + 3758096384 + mfa ->
  getr regs 1 = (0x55b7c : bv 64)%bv -> getr regs 2 = Z_to_bv 64 (sp - 64) -> getr regs 10 = Z_to_bv 64 1303448 -> getr regs 11 = Z_to_bv 64 r ->
  getr regs 12 = Z_to_bv 64 (spb + c * 2 ^ 32) -> getr regs 13 = Z_to_bv 64 total ->
  0x698000 + 512 <= sp -> sp < 2 ^ 47 -> 1 <= c <= 30 -> 0x698000 <= r -> r + 128 <= sp - 512 -> 0 <= spb -> spb + 2 ^ 37 < 2 ^ 47 -> spb = 65536 * qs ->
  0 <= total -> 0 <= mfa < 4 * total -> mfa = 262144 * kf -> 4 * total + 262143 = 262144 * q + rr -> 0 <= rr < 262144 -> 262144 * q <= 536870912 ->
  wrA M (sp - 512) 448 ->
  cellA M (r + 24) 8 mfa -> cellA M (1303448 + 56) 1 0 ->
  cellA M 0x139198 8 0x1d14a0 -> cellA M 0x1d14a0 8 4096 -> cellA M 0x1391a8 8 0x1d3528 -> cellA M (0x1d3528 + 260) 1 0 ->
  exists regs' M',
    msteps ASEGS (mkst regs (0x55d40 : word) M rom) (mkst regs' (0x8c604 : word) M' rom)
    /\ art_mmap_args regs' addr2 (262144 * q - mfa) 50
    /\ getr regs' 1 = Z_to_bv 64 0x8e3c4 /\ getr regs' 2 = Z_to_bv 64 (sp - 112 - 128) /\ getr regs' 8 = Z_to_bv 64 (262144 * q - mfa)
    /\ (forall x : reg, In x [3; 4; 21; 22; 23; 24; 25; 26; 27]%bv -> getr regs' x = getr regs x)
    /\ mem_grows M M' /\ art_agree [(sp - 512, 448)] M M'
    /\ cellA M' (sp - 64 - 8) 8 0x55b7c /\ cellA M' (sp - 64 - 16) 8 (U (getr regs 8)) /\ cellA M' (sp - 64 - 24) 8 (U (getr regs 9))
    /\ cellA M' (sp - 64 - 32) 8 (U (getr regs 18)) /\ cellA M' (sp - 64 - 40) 8 (U (getr regs 19))
    /\ cellA M' (sp - 112 - 8) 8 0x55de0 /\ cellA M' (sp - 112 - 16) 8 (262144 * q) /\ cellA M' (sp - 112 - 24) 8 addr2 /\ cellA M' (sp - 112 - 32) 8 (262144 * q - mfa)
    /\ cellA M' (sp - 112 - 40) 8 0x9657c /\ cellA M' (sp - 112 - 48) 8 (262144 * q - mfa) /\ cellA M' (sp - 112 - 56) 8 addr2 /\ cellA M' (sp - 112 - 64) 8 (262144 * q - mfa)
    /\ cellA M' (sp - 112 - 72) 8 r /\ cellA M' (sp - 112 - 80) 8 (U (getr regs 20)).
