#[using="Type"] Lemma art_rta_Cm2 : forall regs (M rom : word -> option byte) (sp tp key tsd ctx t r c spb qs mfa kf q m1 m2 addr2 len2 shb2 : Z) (g8 g9 g18 g19 g20 : word),
  addr2 = spb + c * 2 ^ 32 + 3758096384 + mfa -> len2 = 262144 * q - mfa -> shb2 = 2147450880 + 8192 * qs + c * 2 ^ 29 + 469762048 + 32768 * kf ->
  getr regs 1 = Z_to_bv 64 0x8e3c4 -> getr regs 2 = Z_to_bv 64 (sp - 112 - 128) -> getr regs 4 = Z_to_bv 64 tp -> getr regs 8 = Z_to_bv 64 len2 -> getr regs 10 = Z_to_bv 64 addr2 ->
  0x698000 + 512 <= sp -> sp < 2 ^ 47 -> 1 <= c <= 30 -> spb = 65536 * qs -> mfa = 262144 * kf -> 0 <= kf -> kf + 1 <= q -> 262144 * q <= 536870912 ->
  kHighMemBeg <= spb -> spb + 2 ^ 37 < 2 ^ 47 ->
  0 <= m1 < 2 ^ 64 -> 0 <= m2 < 2 ^ 64 ->
  4096 <= t -> t + 4096 <= sp - 512 -> 0x698000 <= r -> r + 128 <= sp - 512 -> apart t 4096 r 128 ->
  0x10100 <= tp -> tp + 8 <= 0x698000 -> 0x10000 <= tsd -> tsd + 1024 <= 0x698000 -> 4096 <= ctx -> ctx + 4096 <= sp - 512 ->
  apart shb2 (32768 * (q - kf)) t 4096 -> apart shb2 (32768 * (q - kf)) r 128 -> apart shb2 (32768 * (q - kf)) ctx 4096 -> shb2 + 32768 * (q - kf) <= sp - 512 ->
  wrA M (sp - 512) 400 -> wrA M shb2 (32768 * (q - kf)) -> wrA M (t + 2872) 16 -> wrA M r 128 ->
  art_layout M -> art_tsd M tp key tsd ctx t ->
  cellA M (sp - 64 - 8) 8 0x55b7c -> cellA M (sp - 64 - 16) 8 (U g8) -> cellA M (sp - 64 - 24) 8 (U g9) -> cellA M (sp - 64 - 32) 8 (U g18) -> cellA M (sp - 64 - 40) 8 (U g19) ->
  cellA M (sp - 112 - 8) 8 0x55de0 -> cellA M (sp - 112 - 16) 8 (262144 * q) -> cellA M (sp - 112 - 24) 8 addr2 -> cellA M (sp - 112 - 32) 8 len2 ->
  cellA M (sp - 112 - 40) 8 0x9657c -> cellA M (sp - 112 - 48) 8 len2 -> cellA M (sp - 112 - 56) 8 addr2 -> cellA M (sp - 112 - 64) 8 len2 ->
  cellA M (sp - 112 - 72) 8 r -> cellA M (sp - 112 - 80) 8 (U g20) ->
  cellA M 0x1391a8 8 0x1d3528 -> cellA M (0x1d3528 + 144) 8 0 ->
  cellA M (t + 2872) 8 m1 -> cellA M (t + 2880) 8 m2 ->
  exists regs' M',
    msteps ASEGS (mkst regs (0x8c608 : word) M rom) (mkst regs' (0x55b7c : word) M' rom)
    /\ getr regs' 10 = Z_to_bv 64 1 /\ getr regs' 2 = Z_to_bv 64 (sp - 64)
    /\ getr regs' 8 = g8 /\ getr regs' 9 = g9 /\ getr regs' 18 = g18 /\ getr regs' 19 = g19 /\ getr regs' 20 = g20
    /\ (forall x : reg, In x [3; 4; 21; 22; 23; 24; 25; 26; 27]%bv -> getr regs' x = getr regs x)
    /\ mem_grows M M' /\ art_agree [(sp - 512, 400); (shb2, 32768 * (q - kf)); (t + 2872, 16); (r + 24, 8)] M M'
